    color += vec3(1.0, 0.9, 0.7) * inner * 2.0;

    // Beat pulse
    color *= 1.0 + u_beat * 0.3;

    // Intensity
    color *= u_intensity;

    // Clip to positive Y
    color *= step(flameBase, uv.y);

